package zw.ac.uz.dpdms.alert; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="alert_log") public class AlertLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public String hazard; public String channel; public String recipient; @Column(length=1000) public String message; public String deliveryStatus="QUEUED"; public Instant createdAt=Instant.now(); public Instant deliveredAt;}
